    definition: "Anonymisation is the process of irreversibly altering personal data such that individuals cannot be identified, directly or indirectly, by any means reasonably likely to be used. Truly anonymised data is no longer subject to GDPR.",
    expandedExplanation: "True anonymisation is very difficult — studies have shown that as few as three or four data points can re-identify individuals in supposedly anonymised datasets. Techniques include: data masking, data aggregation, noise injection (differential privacy), and generalisation (replacing exact values with ranges). GDPR does not apply to genuinely anonymous data, making anonymisation valuable for analytics and research. However, if re-identification is possible through linkage with other datasets, it is not truly anonymised. Pseudonymisation replaces identifiers with pseudonyms but is reversible — it is still personal data under GDPR.",
