    definition: "Pseudonymisation is a data processing technique that replaces directly identifying information (name, email, ID) with artificial identifiers (pseudonyms) while keeping a separate mapping that allows re-identification by authorised parties.",
    expandedExplanation: "Unlike anonymisation, pseudonymisation is reversible — the original data can be restored using the mapping table. GDPR considers pseudonymised data to still be personal data (because re-identification is possible), but it is treated more favourably: it satisfies the data protection by design requirement, enables some data processing that would otherwise require more legal justification, and reduces breach risk. Common methods: replacing email with a hash of the email, tokenisation (replacing card numbers with tokens), and encryption where the key is controlled separately.",
