    definition: "Temperature is a hyperparameter that controls the randomness of an LLM's output by scaling the probability distribution over the vocabulary before sampling. Low temperature (near 0) makes outputs deterministic and focused; high temperature (near 2) makes outputs more random and creative.",
    expandedExplanation: "At temperature 0, the model always picks the highest-probability token (greedy decoding) — fully deterministic. At temperature 1.0, tokens are sampled according to their natural probability distribution. At temperature 2.0, low-probability tokens get a much higher chance of being selected, increasing creativity but also incoherence. For factual tasks, code, and structured output: temperature 0–0.2. For creative writing: 0.7–1.2. For brainstorming: 1.0–1.5.",
    useCases: [
      "Deterministic code generation (temperature = 0)",
      "Creative writing and ideation (temperature 0.8–1.2)",
      "Balancing accuracy vs. variety in AI-generated content",
    ],
