    term: "Top-P Sampling (Nucleus Sampling)",
    category: "AI & Machine Learning",
    shortDescription: "LLM sampling strategy selecting from the smallest set of tokens covering P% of probability.",
    metaTitle: "What is Top-P Sampling? Nucleus Sampling in LLMs",
    metaDescription: "Top-P (nucleus sampling) controls LLM output diversity differently than temperature. Learn how it works and when to adjust it.",
    definition: "Top-P sampling (nucleus sampling) is an LLM sampling strategy that selects the next token from the smallest set of tokens whose cumulative probability exceeds a threshold P (e.g. 0.9), dynamically adjusting the number of candidates based on the probability distribution.",
    expandedExplanation: "Unlike top-K (always considers the K most likely tokens), top-P adapts the candidate pool size: when the model is confident (one token has 95% probability), the pool is tiny; when the model is uncertain, the pool includes many tokens. Top-P 0.9 means: include tokens until 90% of the probability mass is covered. Practitioners typically use either temperature or top-P, not both — adjusting temperature alone is simpler and most common. Top-P is sometimes called nucleus sampling after the nucleus of the probability distribution.",
