    definition: "Caching is the practice of storing the results of expensive computations, database queries, or network requests in a faster storage medium (memory, CDN) so future requests can be served quickly without repeating the work.",
    expandedExplanation: "Cache levels: browser cache (HTML/CSS/JS/images stored locally, controlled by Cache-Control headers), CDN cache (static assets at edge nodes), application cache (Redis, Memcached for computed data), and database query cache. Cache invalidation — knowing when to evict stale data — is one of computer science's famously hard problems. Strategies: time-based expiry (TTL), event-based invalidation (flush on write), and cache-aside (check cache, miss → load from DB → populate cache).",
