    expandedExplanation: "Flexbox operates on two axes: the main axis (controlled by flex-direction: row or column) and the cross axis (perpendicular to main). Key properties: flex-direction sets the main axis direction. justify-content aligns items along the main axis (flex-start, center, space-between, space-around, space-evenly). align-items aligns items along the cross axis (stretch, flex-start, flex-end, center, baseline). flex-wrap controls whether items wrap to new lines. On flex items: flex-grow controls how much the item grows relative to siblings. flex-shrink controls how items shrink when there's not enough space. flex-basis sets the initial size before flex growth/shrink. The shorthand flex: 1 means flex-grow: 1; flex-shrink: 1; flex-basis: 0.",
