    definition: "Core Web Vitals are a set of three performance metrics defined by Google that measure real-world user experience: Largest Contentful Paint (LCP), Interaction to Next Paint (INP), and Cumulative Layout Shift (CLS).",
    expandedExplanation: "LCP measures loading performance — how long until the largest visible element is painted. Good: under 2.5s. INP (replaced FID in March 2024) measures responsiveness — the slowest interaction in the session. Good: under 200ms. CLS measures visual stability — unexpected layout shifts that cause users to misclick. Good: under 0.1. Core Web Vitals are a confirmed Google ranking factor since 2021. They are measured using field data (real users via Chrome UX Report) not just lab data. Key improvements: LCP — optimize images, use a CDN, preload critical resources. INP — defer heavy JavaScript, break up long tasks. CLS — always set explicit dimensions on images and embeds.",
