    metaDescription: "LCP (Largest Contentful Paint) measures how long it takes for the largest visible element on screen to fully load. Good LCP is under 2.5 seconds. Learn how to optimize it.",
    definition: "Largest Contentful Paint (LCP) is a Core Web Vital that measures the render time of the largest image or text block visible within the viewport, relative to when the page first started loading.",
    expandedExplanation: "LCP candidates: img elements, video poster images, background images loaded via CSS url(), and block-level text elements. The element changes during load — the initial LCP candidate may be replaced by a larger element discovered later. Good LCP: under 2.5s. Needs improvement: 2.5–4.0s. Poor: over 4.0s. Top LCP improvements: Use a CDN for assets. Preload the LCP image: <link rel='preload' as='image' href='hero.jpg'>. Reduce server response time (TTFB). Avoid lazy-loading the LCP image. Compress and serve next-gen formats (WebP, AVIF). Eliminate render-blocking resources.",
