    metaDescription: "CLS measures unexpected layout shifts that cause pages to jump as they load. Good CLS is under 0.1. Learn common causes and how to fix layout instability.",
    definition: "Cumulative Layout Shift (CLS) is a Core Web Vital that measures the largest burst of layout shift scores for unexpected layout shifts that occur during a page's entire lifespan.",
    expandedExplanation: "A layout shift occurs when a visible element changes its position between two rendered frames. CLS score = impact fraction × distance fraction. Good: under 0.1. Needs improvement: 0.1–0.25. Poor: over 0.25. Common CLS causes: Images without explicit width and height attributes (browser doesn't know how much space to reserve). Ads, embeds, or iframes without reserved space. Dynamically injected content above existing content. Web fonts causing flash of unstyled text (FOUT). Fixes: Always set width and height on images. Reserve space for ads with min-height. Use font-display: optional to prevent FOUT shifts. Avoid inserting content above the fold after load.",
