    definition: "Cross-Site Scripting (XSS) is a type of security vulnerability where attackers inject malicious client-side scripts into web pages that are then executed in the browsers of other users who view those pages.",
    expandedExplanation: "XSS types: Stored XSS (Persistent) — malicious script is saved in the database and served to all users who view the content. Reflected XSS — malicious script is in the URL and reflected back in the response without storage. DOM-based XSS — the vulnerability exists in client-side code that processes user input and writes it to the DOM. Prevention: Output encoding — encode user input before rendering in HTML. Use textContent instead of innerHTML for user-supplied text. Content Security Policy (CSP) prevents inline scripts. HTTPOnly cookies prevent script access to session tokens. Sanitization libraries (DOMPurify) for rich text content. Frameworks like React, Vue, and Angular escape output by default — XSS vulnerabilities are common in manual DOM manipulation.",
