    expandedExplanation: "Classic example: A login form that concatenates input into 'SELECT * FROM users WHERE username=' + input. Entering admin'-- comments out the password check, bypassing authentication. SQLi can: Read any data from the database. Modify or delete data. Execute administrative operations. In some cases, execute OS commands. Prevention: Parameterized queries / prepared statements — the only reliable defense. The query structure is fixed; user input is always treated as data, never SQL. ORMs (Sequelize, Prisma, Hibernate) use parameterized queries internally. Input validation adds defense-in-depth but is not sufficient alone. OWASP ranks SQL injection as one of the top web vulnerabilities. Modern ORMs make parameterized queries the default path, dramatically reducing SQLi risk in new applications.",
