    expandedExplanation: "CSP is delivered via the Content-Security-Policy HTTP header or <meta> tag. Key directives: default-src sets the fallback for all resource types. script-src controls JavaScript sources. style-src controls CSS sources. img-src controls image sources. connect-src controls fetch/XHR/WebSocket connections. Values: 'self' (same origin). 'none' (block all). 'nonce-<base64>' (allow inline scripts with matching nonce). Specific domains. Hash-based: 'sha256-<hash>'. Strict CSP uses nonces or hashes to allow only specific inline scripts. CSP reporting: use report-to or report-uri to receive violation reports without blocking (report-only mode). CSP is the strongest available defense against XSS — even if an attacker injects a script tag, the browser refuses to execute it without the correct nonce or hash.",
