    expandedExplanation: "Same-origin policy: browsers block cross-origin requests by default. CORS allows servers to opt in to cross-origin access via response headers. Key headers: Access-Control-Allow-Origin: * (allow all origins) or specify a domain. Access-Control-Allow-Methods: GET, POST, PUT, DELETE. Access-Control-Allow-Headers: Content-Type, Authorization. Preflight requests: browsers send an OPTIONS preflight for non-simple requests (non-GET/HEAD/POST, custom headers, JSON content type) to check if CORS allows it. With credentials: if the request includes cookies, the server must set Access-Control-Allow-Credentials: true and specify an explicit origin (not *). CORS errors are browser enforcements — the request actually reaches the server; the browser just blocks JavaScript from reading the response. The server must explicitly enable CORS.",
