    expandedExplanation: "Service workers sit between the web application and the network — they can intercept requests and serve cached responses. Lifecycle: register → install (cache assets) → activate (clean old caches) → fetch (intercept requests). Caching strategies: Cache-first (serve from cache, fall back to network — fast but potentially stale). Network-first (try network, fall back to cache — fresh but slower). Stale-while-revalidate (serve cache immediately, update in background). Requirements: HTTPS only (or localhost for development). Runs in its own thread — no DOM access. Persistent beyond page lifetime. Service workers are the foundation of Progressive Web Apps (PWAs). Workbox (Google) simplifies service worker implementation.",
