    definition: "A Promise is a JavaScript object that represents the eventual completion or failure of an asynchronous operation, providing a cleaner alternative to nested callbacks.",
    expandedExplanation: "Promise states: Pending (initial state). Fulfilled (completed successfully). Rejected (failed). Promises are chained with .then() (success), .catch() (error), .finally() (always runs). async/await is syntactic sugar over Promises — await pauses execution until the Promise resolves. Promise combinators: Promise.all([p1, p2, p3]) — resolves when all resolve, rejects if any rejects. Promise.allSettled() — waits for all, returns array of results regardless of outcome. Promise.race() — resolves/rejects with the first settled Promise. Promise.any() — resolves with first fulfillment (ignores rejections). Common mistakes: Not returning Promises in .then() chains (breaks chaining). Forgetting .catch() (unhandled rejections). Not handling all error paths in async functions.",
