    definition: "async/await is a JavaScript syntax that enables writing asynchronous, Promise-based code in a synchronous style using the async function declaration and await expression.",
    expandedExplanation: "async function: always returns a Promise. await expression: pauses async function execution until the awaited Promise resolves. The async function resumes with the resolved value. Error handling: use try/catch with await, just like synchronous code. Parallel execution: const [a, b] = await Promise.all([fetchA(), fetchB()]) — don't await in sequence unless the operations depend on each other. Common mistakes: await in a loop with sequential execution — use Promise.all for parallel. Not using try/catch — unhandled async errors cause uncaught Promise rejections. Top-level await in modules (ES2022) — await at the module level without an async wrapper. async/await doesn't eliminate Promises — it's built on top of them. Under the hood, an async function returning a value is equivalent to returning Promise.resolve(value).",
