    expandedExplanation: "How indexes work: Without an index, a SELECT WHERE requires a full table scan — O(n). With a B-tree index, the database navigates the tree to find matching rows — O(log n). PostgreSQL index types: B-tree (default — equality and range queries). Hash (equality only). GIN (arrays, full-text search, JSON). GiST (geometric data, full-text). BRIN (large sequential data like timestamps). Index trade-offs: Speed up reads. Slow down writes (indexes must be updated on INSERT, UPDATE, DELETE). Use storage space. Composite indexes: index on multiple columns. Order matters — an index on (a, b) helps queries on a and queries on (a, b), but not queries on b alone. Index selectivity: high-selectivity columns (UUID, email) benefit more from indexing than low-selectivity (boolean) columns. EXPLAIN ANALYZE in PostgreSQL shows whether indexes are being used.",
