    expandedExplanation: "Rendering patterns compared: CSR (Client-Side Rendering) — browser receives empty HTML, downloads JS, runs it to render content. Fast after first load, slow initial paint, poor SEO for SPAs. SSR — server renders HTML for each request. Good initial load, good SEO, but server costs increase with traffic. SSG (Static Site Generation) — HTML pre-built at build time. Fastest possible load, best for content that doesn't change per user. ISR (Incremental Static Regeneration, Next.js) — static pages regenerated in the background at a defined interval — the best of SSR and SSG. RSC (React Server Components, Next.js App Router) — components that render on the server, have direct database access, and send zero JS to the client. Hydration: after SSR sends HTML, React attaches event handlers on the client — this is hydration. Hydration mismatch errors occur when server and client render differently.",
