    definition: "HTTP (Hypertext Transfer Protocol) is an application-layer protocol that defines how clients (browsers) and servers communicate by exchanging requests and responses, forming the foundation of the World Wide Web.",
    expandedExplanation: "HTTP is stateless — each request is independent. HTTP request components: Method (GET, POST, PUT, PATCH, DELETE). URL. Headers (Host, Content-Type, Authorization, Cookie, Accept). Body (for POST/PUT/PATCH). HTTP response: Status code. Headers (Content-Type, Set-Cookie, Cache-Control, CORS headers). Body. HTTP versions: HTTP/1.1 — text protocol, one request per TCP connection (or pipelining with head-of-line blocking issues). HTTP/2 — binary, multiplexing (multiple requests over one connection), header compression (HPACK), server push. HTTP/3 — built on QUIC (UDP-based), eliminates TCP head-of-line blocking, faster connection establishment. HTTPS = HTTP + TLS encryption. TLS handshake adds latency — HTTP/3's 0-RTT reduces this. Keep-Alive (HTTP/1.1): reuse TCP connections for multiple requests, reducing handshake overhead.",
