    metaDescription: "Unit testing verifies individual functions or components work correctly in isolation. Learn about test runners (Jest, Vitest), assertions, mocking, and test-driven development (TDD).",
    definition: "Unit testing is the practice of testing individual functions, methods, or components in isolation — with dependencies mocked or stubbed — to verify they produce correct output for given inputs.",
    expandedExplanation: "Unit tests are fast (no I/O, no database), deterministic, and easy to debug. Test structure (AAA pattern): Arrange (set up test data and mocks). Act (call the function). Assert (verify the output). JavaScript test runners: Jest (most popular, includes mocking, assertions, coverage). Vitest (Vite-native, compatible API, faster). Mocha + Chai (older, more modular). Testing pure functions is straightforward. Testing components with side effects requires mocking: jest.mock() replaces modules. vi.fn() creates mock functions. Spy on calls with toHaveBeenCalledWith(). React component testing: React Testing Library (test behavior, not implementation — queryByText, userEvent.click). Enzyme (implementation-focused, less popular now). Test coverage: percentage of code lines executed during tests. High coverage doesn't mean bug-free — tests must assert meaningful behavior. Aim for 80%+ coverage of business logic.",
