    expandedExplanation: "E2E tests use a real browser controlled by the test framework. Tools: Playwright (Microsoft, supports Chromium/Firefox/WebKit, fast, reliable, excellent API). Cypress (developer-friendly, real-time test runner, built-in retrying). Selenium (older, cross-browser, slower). Puppeteer (Chromium only, lower-level). E2E test strategies: Test critical paths only (login, checkout, signup — not every edge case). Use data-testid attributes for stable selectors. Avoid testing third-party integrations in E2E (mock external services). Parallelize tests across browsers. E2E test challenges: Slow (minutes, not seconds). Flaky due to timing, network, or browser differences. Hard to debug failures. Use Playwright's trace viewer to debug failed tests step-by-step. The test pyramid: many unit tests → fewer integration tests → few E2E tests. E2E tests are most valuable when they cover flows where multiple services interact.",
