    metaDescription: "WCAG (Web Content Accessibility Guidelines) is the international standard for web accessibility. Learn WCAG levels (A, AA, AAA), the four POUR principles, and how to meet WCAG 2.1 AA compliance.",
    definition: "The Web Content Accessibility Guidelines (WCAG) are internationally recognized standards published by the W3C that specify how to make web content accessible to people with disabilities.",
    expandedExplanation: "WCAG is organized around four principles (POUR): Perceivable — content must be presentable in ways users can perceive (alt text for images, captions for videos, sufficient color contrast). Operable — UI must be operable (keyboard navigable, no seizure-inducing content, enough time). Understandable — content must be understandable (readable, predictable, error identification). Robust — content must work with assistive technologies (screen readers, voice control). Conformance levels: Level A — minimum requirements (most critical barriers). Level AA — the most commonly required level (GDPR, ADA, EN 301 549). Level AAA — highest level, not required for entire sites. WCAG 2.1 (2018) added mobile, cognitive, and low vision criteria. WCAG 2.2 (2023) added more focus indicators and touch target size requirements. Legal requirements: ADA (US), Equality Act (UK), EN 301 549 (EU), AODA (Canada) all reference WCAG 2.1 AA.",
