    definition: "ARIA (Accessible Rich Internet Applications) is a set of HTML attributes (roles, states, and properties) that add semantic meaning to web content, making it understandable to assistive technologies like screen readers.",
    expandedExplanation: "ARIA adds meaning that native HTML doesn't convey. ARIA attributes: role — defines what an element is (role='button', role='dialog', role='alert'). aria-label — provides an accessible name (aria-label='Close dialog'). aria-labelledby — references another element as the label. aria-describedby — references descriptive text. aria-hidden='true' — hides from screen readers (decorative icons). aria-expanded, aria-selected, aria-checked — convey state. First rule of ARIA: don't use ARIA if native HTML can do the job. <button> is better than <div role='button'>. Use <nav>, <main>, <header>, <footer> landmark elements. ARIA live regions (aria-live) announce dynamic content changes: aria-live='polite' (waits for user to finish). aria-live='assertive' (interrupts immediately — use sparingly). Focus management: when opening a modal, move focus into it. Return focus to the trigger when the modal closes.",
