    expandedExplanation: "WCAG contrast requirements: Normal text (< 18pt or 14pt bold): 4.5:1 minimum (AA), 7:1 (AAA). Large text (≥ 18pt or 14pt bold): 3:1 (AA), 4.5:1 (AAA). UI components and graphics (icons, chart elements): 3:1 (AA). Color blindness affects ~8% of males and ~0.5% of females. Never rely on color alone to convey information — add a pattern, icon, or text label. Common contrast failures: Light gray text on white background. Placeholder text in form fields (typically too low contrast). Disabled element text (WCAG exempts disabled elements but best practice is still readable). Testing: Browser DevTools accessibility panel. axe browser extension. WebAIM Contrast Checker. Automated in CI with axe-core or Lighthouse. Toolora's Color Contrast Checker can validate any color pair instantly.",
