    definition: "ETL (Extract, Transform, Load) is a data integration process that extracts data from source systems, transforms it (cleaning, aggregating, reformatting), and loads it into a destination system like a data warehouse.",
    expandedExplanation: "ETL stages: Extract — pull data from source systems: databases, APIs, files (CSV, JSON, XML), event streams. Transform — clean (handle nulls, duplicates, format errors), standardize (date formats, currency, units), enrich (join with reference data), aggregate (SUM, COUNT, AVG). Load — write transformed data to the target: data warehouse, data lake, database, analytics platform. ETL vs ELT: In traditional ETL, transformation happens before loading (in a staging area). In ELT (Extract, Load, Transform), raw data is loaded first, then transformed inside the target system (e.g., Snowflake, BigQuery) using SQL. ELT is preferred for modern cloud data warehouses — massive compute power makes in-database transformation fast and scalable. ETL tools: Apache Airflow (orchestration), dbt (transformation), Fivetran/Airbyte (managed connectors), Apache Spark (large-scale processing).",
