    expandedExplanation: "Data warehouse vs operational database (OLTP): OLTP (Online Transaction Processing) databases (PostgreSQL, MySQL) are optimized for fast reads/writes of individual records — power applications. OLAP (Online Analytical Processing) data warehouses are optimized for complex aggregations across millions of rows — power analytics. Data warehouse characteristics: Integrated (data from many sources). Non-volatile (historical data preserved). Time-variant (tracks changes over time). Subject-oriented (organized around business domains). Modern cloud data warehouses: Snowflake (separate compute and storage, scales independently). Google BigQuery (serverless, pay-per-query). Amazon Redshift (columnar storage, integrated AWS ecosystem). Databricks Lakehouse (combines data lake and warehouse). Columnar storage: data warehouses store data by column, not row — dramatically faster for analytical queries that aggregate one or two columns across millions of rows.",
