    expandedExplanation: "Architecture: Input layer (receives raw data). Hidden layers (learn intermediate representations). Output layer (final prediction). Each connection has a weight. Each neuron applies an activation function (ReLU, sigmoid, softmax) to its weighted sum of inputs. Training: Backpropagation computes the gradient of the loss function with respect to each weight. Gradient descent updates weights to minimize loss. Epochs: full passes through the training data. Batch size: number of examples per weight update. Deep learning = neural networks with many hidden layers. Types: Feedforward (MLP) — basic. CNN (Convolutional Neural Network) — spatial data (images). RNN/LSTM — sequential data (text, time series). Transformer — attention-based, powers LLMs (BERT, GPT). Challenges: Overfitting (memorizes training data, generalizes poorly — fix: regularization, dropout, more data). Vanishing gradient (deep networks stop learning — fix: ReLU, batch norm, residual connections).",
