    definition: "Fine-tuning is the process of taking a pre-trained machine learning model and continuing to train it on a smaller, domain-specific dataset to adapt it to a particular task or style.",
    expandedExplanation: "Why fine-tune? Pre-trained models (LLMs, image models) learn general representations. Fine-tuning specializes them for specific tasks: medical question answering, legal document classification, a company's writing style. Fine-tuning vs prompt engineering: Prompt engineering (few-shot examples, system prompts) costs nothing and is the right starting point. Fine-tuning is appropriate when prompt engineering can't achieve the needed consistency, when a specific style or format is required, or when latency/cost savings from a smaller model matter. Parameter-efficient fine-tuning: Full fine-tuning (update all weights) is expensive. LoRA (Low-Rank Adaptation) — add small trainable matrices to frozen layers. Dramatically reduces training cost. QLoRA — LoRA with quantized base model (4-bit) — fine-tune on consumer GPUs. RLHF (Reinforcement Learning from Human Feedback) — fine-tune with human preference ratings. Used to align GPT-4, Claude, Gemini.",
