    expandedExplanation: "Prompting techniques: Zero-shot — just describe the task. Simple and works well for well-trained models. Few-shot — provide examples of input/output pairs in the prompt. Significantly improves consistency. Chain-of-thought (CoT) — instruct the model to 'think step by step'. Dramatically improves reasoning tasks. Self-consistency — generate multiple chain-of-thought responses, take the majority answer. System prompts — set the model's persona, tone, constraints, and output format. Instruct the model how to behave, not just what to do. Structured output: instruct the model to respond in JSON or XML for reliable parsing. Use schemas. Hallucination mitigation: Tell the model to say 'I don't know' when uncertain. Ground responses with retrieved context (RAG). Prompt injection attacks: malicious user input overrides system instructions — sanitize inputs, use separate trust boundaries. LLM APIs expose system/user/assistant message roles for conversational context.",
