    definition: "Encryption is the process of encoding information using a cryptographic algorithm so that only parties with the correct decryption key can read it, protecting data confidentiality.",
    expandedExplanation: "Symmetric encryption: the same key encrypts and decrypts. Fast. AES-256 is the standard. Problem: how do you securely share the key? Asymmetric encryption: public key encrypts, private key decrypts (or private key signs, public key verifies). RSA, ECC. Slower. Used for key exchange and digital signatures. Hybrid encryption (used in TLS): asymmetric encryption exchanges a session key, then symmetric encryption uses that key for bulk data. Encryption at rest: encrypting stored data (database fields, disk encryption). Encryption in transit: TLS encrypts data moving over networks. End-to-end encryption (E2EE): only the sender and recipient can read messages — the service provider cannot. Used by Signal, WhatsApp. Hashing vs encryption: encryption is reversible (with the key). Hashing is one-way — used for passwords (bcrypt, Argon2). Never encrypt passwords — hash them. Key management: storing encryption keys securely is as important as the encryption algorithm itself (use HSMs or KMS like AWS KMS).",
